    $c.util.getComponent("ipt_secutizAdmInstNm").setValue(parentfm.secutiz_adm_inst_nm.value);
    $c.util.getComponent("ipt_secutizChrgNm").setValue(parentfm.secutiz_chrg_nm.value);
    $c.util.getComponent("ipt_secutizChrgTelNo").setValue(parentfm.secutiz_chrg_tel_no.value);
    const secutiz_chrg_tel_no = parentfm.secutiz_chrg_tel_no.value;
    if (secutiz_chrg_tel_no != null && secutiz_chrg_tel_no !== '') {
        const secutiz_chrg_tel_no_arr = secutiz_chrg_tel_no.split('-');
        $c.util.getComponent("ipt_secutizChrgTelNo1").setValue(secutiz_chrg_tel_no_arr[0]);
        $c.util.getComponent("ipt_secutizChrgTelNo2").setValue(secutiz_chrg_tel_no_arr[1]);
        $c.util.getComponent("ipt_secutizChrgTelNo3").setValue(secutiz_chrg_tel_no_arr[2]);
    }
    $c.util.getComponent("ipt_encrypSecutizChrgEmail").setValue(parentfm.encryp_secutiz_chrg_email.value);
    const encryp_secutiz_chrg_email = parentfm.encryp_secutiz_chrg_email.value;
    if (encryp_secutiz_chrg_email != null && encryp_secutiz_chrg_email !== '') {
        const encryp_secutiz_chrg_email_arr = encryp_secutiz_chrg_email.split('@');
        $c.util.getComponent("ipt_encrypSecutizChrgEmail1").setValue(encryp_secutiz_chrg_email_arr[0]);
        $c.util.getComponent("ipt_encrypSecutizChrgEmail2").setValue(encryp_secutiz_chrg_email_arr[1]);
    }
    $c.util.getComponent("ipt_secutizSchdlIsuTotamt").setValue(parentfm.secutiz_schdl_isu_totamt.value);
    $c.util.getComponent("ipt_secutizAsstTotValuAmt").setValue(parentfm.secutiz_asst_tot_valu_amt.value);
    $c.util.getComponent("ipt_creditRefoceMethdContn").setValue(parentfm.credit_refoce_methd_contn.value);
    $c.util.getComponent("ipt_secutizMiscMemoContn").setValue(parentfm.secutiz_misc_memo_contn.value);
    const asst_count = parseInt(parentfm.asst_count.value);
    for (let i = 0; i < asst_count; i++) {
        if (asst_count == 1) {
            eval("fm.asst_hd_inst_cd" + (i + 1)).value = parentfm.asst_hd_inst_cd.value;
            eval("fm.asst_hd_inst_nm" + (i + 1)).value = parentfm.asst_hd_inst_nm.value;
            eval("fm.asst_hd_tp_cd" + (i + 1)).value = parentfm.asst_hd_tp_cd.value;
            eval("fm.secutiz_asst_tp_cd" + (i + 1)).value = parentfm.secutiz_asst_tp_cd.value;
            eval("fm.asst_adm_inst_cd" + (i + 1)).value = parentfm.asst_adm_inst_cd.value;
            eval("fm.asst_adm_inst_nm" + (i + 1)).value = parentfm.asst_adm_inst_nm.value;
            $c.util.getComponent("ipt_asstHdInstMiscContn").setValue(parentfm.asst_hd_inst_misc_contn.value);
            $c.util.getComponent("ipt_asstHdTpMiscContn").setValue(parentfm.asst_hd_tp_misc_contn.value);
            $c.util.getComponent("ipt_secutizAsstTpMiscContn").setValue(parentfm.secutiz_asst_tp_misc_contn.value);
            $c.util.getComponent("ipt_asstAdmInstMiscContn").setValue(parentfm.asst_adm_inst_misc_contn.value);
        } else {
            if ((i + 1) <= asst_count) {
                eval("fm.asst_hd_inst_cd" + (i + 1)).value = parentfm.asst_hd_inst_cd[i].value;
                eval("fm.asst_hd_inst_nm" + (i + 1)).value = parentfm.asst_hd_inst_nm[i].value;
                eval("fm.asst_hd_tp_cd" + (i + 1)).value = parentfm.asst_hd_tp_cd[i].value;
                eval("fm.secutiz_asst_tp_cd" + (i + 1)).value = parentfm.secutiz_asst_tp_cd[i].value;
                eval("fm.asst_adm_inst_cd" + (i + 1)).value = parentfm.asst_adm_inst_cd[i].value;
                eval("fm.asst_adm_inst_nm" + (i + 1)).value = parentfm.asst_adm_inst_nm[i].value;
            }
            if (i == 0) {
                $c.util.getComponent("ipt_asstHdInstMiscContn").setValue(parentfm.asst_hd_inst_misc_contn[0].value);
                $c.util.getComponent("ipt_asstHdTpMiscContn").setValue(parentfm.asst_hd_tp_misc_contn[0].value);
                $c.util.getComponent("ipt_secutizAsstTpMiscContn").setValue(parentfm.secutiz_asst_tp_misc_contn[0].value);
                $c.util.getComponent("ipt_asstAdmInstMiscContn").setValue(parentfm.asst_adm_inst_misc_contn[0].value);
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};


