 * @hidden N
*/
scwin.checkInput = async function (objCd, objName, div) {
    /* sdd-asis-lifecycle:begin checkInput — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    fm = (document.InputForm || { elements: [] });
    const preDiv = parseInt(div) - 1;
    if ($c.util.getComponent("fm." + objName + preDiv).value === '') {
        await $c.win.alert(preDiv + "차 기관 입력이 누락되었습니다.");
        console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return false;
    } else {
        window_iss_inst_cd(objCd + div, objName + div);
    }
    /* sdd-asis-lifecycle:end */
};


